1	package loja.checkout.pagamento;
2	
3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	
6	import org.springframework.stereotype.Component;
7	
8	import loja.checkout.Dinheiro;
9	
10	@Component
11	class Cartao implements FormaPagamento {
12	
13	    private static final int MAXIMO_PARCELAS = 12;
14	    private static final int MAXIMO_SEM_JUROS = 3;
15	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
16	
17	    @Override
18	    public String codigo() {
19	        return "CARTAO";
20	    }
21	
22	    @Override
23	    public boolean parcelasPermitidas(int parcelas) {
24	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
25	    }
26	
27	    @Override
28	    public Cobranca cobrar(BigDecimal totalPedido, int parcelas) {
29	        BigDecimal quantidade = BigDecimal.valueOf(parcelas);
30	        if (parcelas <= MAXIMO_SEM_JUROS) {
31	            return new Cobranca(totalPedido, Dinheiro.arredondar(totalPedido.divide(quantidade, MathContext.DECIMAL128)));
32	        }
33	        BigDecimal parcela = Dinheiro.arredondar(parcelaPrice(totalPedido, parcelas));
34	        return new Cobranca(parcela.multiply(quantidade), parcela);
35	    }
36	
37	    /** Tabela Price: total × taxa ÷ (1 − (1 + taxa)^−n). */
38	    private BigDecimal parcelaPrice(BigDecimal total, int parcelas) {
39	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas);
40	        BigDecimal desconto = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, MathContext.DECIMAL128));
41	        return total.multiply(TAXA_MENSAL).divide(desconto, MathContext.DECIMAL128);
42	    }
43	}
